(function(root){
function parseCSV(text){text=String(text).replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false,closed=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=c;}else if(c==='"'){if(cell||closed)throw Error('CSV 引号位置无效');quoted=true;}else if(c===','){row.push(cell);cell='';closed=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';closed=false;}else{if(closed&&!/\s/.test(c))throw Error('CSV 引号后有非法字符');if(!closed)cell+=c;}}if(quoted)throw Error('CSV 引号未闭合');if(cell||row.length){row.push(cell);if(row.some(v=>v.trim()))rows.push(row);}if(rows.length>2001)throw Error('最多支持 2000 条记录');return rows;}
function preflight(buffer){const u=new Uint8Array(buffer),v=new DataView(buffer);if(u.length>15*1024*1024)throw Error('文件超过 15MB');let e=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){e=i;break;}if(e<0)throw Error('不是有效的 XLSX 文件');if(v.getUint16(e+4,true)||v.getUint16(e+6,true))throw Error('不支持多卷 ZIP');const n=v.getUint16(e+10,true),start=v.getUint32(e+16,true);if(n>500||start>u.length)throw Error('工作簿过大或格式不支持');let p=start,total=0;for(let i=0;i<n;i++){if(p+46>u.length||v.getUint32(p,true)!==0x02014b50)throw Error('XLSX 压缩目录损坏');if(v.getUint16(p+8,true)&1)throw Error('不支持加密工作簿');total+=v.getUint32(p+24,true);p+=46+v.getUint16(p+28,true)+v.getUint16(p+30,true)+v.getUint16(p+32,true);if(total>40*1024*1024)throw Error('解压后超过 40MB，请精简工作簿');}}
function xml(s){const d=new DOMParser().parseFromString(s,'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('Excel XML 格式损坏');return d;}
const nodes=(d,n)=>[...d.getElementsByTagNameNS('*',n)];
const strings=d=>nodes(d,'t').map(n=>n.textContent).join('');
async function readXlsx(buffer){preflight(buffer);const zip=await root.JSZip.loadAsync(buffer);const get=async name=>{const f=zip.file(name);if(!f)throw Error('工作簿缺少 '+name);return xml(await f.async('string'));};const wb=await get('xl/workbook.xml'),rels=await get('xl/_rels/workbook.xml.rels'),relationships=new Map(nodes(rels,'Relationship').filter(n=>n.getAttribute('TargetMode')!=='External').map(n=>[n.getAttribute('Id'),n.getAttribute('Target')]));const ss=zip.file('xl/sharedStrings.xml')?nodes(await get('xl/sharedStrings.xml'),'si').map(strings):[];const props=nodes(wb,'workbookPr')[0],date1904=props&&['1','true'].includes(props.getAttribute('date1904'));const sheets=[];for(const sheet of nodes(wb,'sheet')){const id=sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||sheet.getAttribute('r:id'),target=relationships.get(id);if(!target)continue;const path=target.startsWith('/')?target.slice(1):'xl/'+target;const canonical=[];path.split('/').forEach(p=>{if(p==='..')canonical.pop();else if(p&&p!=='.')canonical.push(p);});const doc=await get(canonical.join('/')),rows=[];const sheetRows=nodes(doc,'row');if(sheetRows.length>2001)throw Error('每张表最多支持 2000 条记录');for(const r of sheetRows){const idx=Number(r.getAttribute('r'));if(!Number.isInteger(idx)||idx<1||idx>2100)throw Error('行号超出支持范围');const cells=[];for(const c of nodes(r,'c')){const addr=c.getAttribute('r')||'',letters=addr.match(/^[A-Z]+/);if(!letters)throw Error('单元格地址无效');let col=0;for(const ch of letters[0])col=col*26+ch.charCodeAt(0)-64;col--;if(col>99)throw Error('最多支持 100 列');const t=c.getAttribute('t'),f=nodes(c,'f')[0],value=nodes(c,'v')[0]?.textContent;let val='';if(t==='e')val='[单元格错误]';else if(t==='inlineStr')val=strings(c);else if(t==='s')val=ss[Number(value)]??'';else if(t==='str')val=value??'';else if(t==='d')val=(value??'').slice(0,10);else if(value!==undefined)val=Number(value);else if(f)val='[公式无缓存，请在 Excel 重算后保存]';cells[col]=val;}rows[idx-1]=cells;}for(let i=0;i<rows.length;i++)rows[i]??=[];sheets.push({name:sheet.getAttribute('name'),rows});}if(!sheets.length)throw Error('没有可读取的工作表');return {sheets,date1904:!!date1904};}
async function readFile(file){if(file.size>15*1024*1024)throw Error('文件超过 15MB');if(/\.csv$/i.test(file.name)){const bytes=new Uint8Array(await file.arrayBuffer());let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{ text=new TextDecoder('gb18030',{fatal:true}).decode(bytes);}return {sheets:[{name:'CSV',rows:parseCSV(text)}],date1904:false};}if(!/\.xlsx$/i.test(file.name))throw Error('支持 .xlsx 和 .csv；请把 .xls 或加密文件另存为 .xlsx');return readXlsx(await file.arrayBuffer());}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(root.ReconEngine.csvCell).join(',')).join('\r\n');}
const api={parseCSV,preflight,readXlsx,readFile,csv};root.ReconIO=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
